export interface SectorLocal {
  nombre: string;
  descripcion: string;
  icon: string; // restaurant | building | health | shop | briefcase | sun | anchor | factory | leaf | home | star | flask
  keywords: string[];
}

export interface Testimonio {
  nombre: string;
  sector: string;
  texto: string;
}

export interface FAQ {
  q: string;
  a: string;
}

export interface Pueblo {
  slug: string;
  nombre: string;
  comarca: string;
  poblacion?: number;
  destacado?: boolean;
  descripcion: string;
  caracteristicas: string[];
  coords?: [number, number]; // [lng, lat] para mapas
  lugarIconico?: string;
  sectorPrincipal?: string;
  sectores?: SectorLocal[];
  testimonios?: Testimonio[];
  faqs?: FAQ[];
  /** Panorama digital local — 2-3 párrafos ÚNICOS por pueblo (contexto económico real). */
  panorama?: string[];
  /** Hitos/datos locales únicos (clave → valor) que se muestran como rejilla de cifras. */
  hitos?: { k: string; v: string }[];
}

